import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../../core/presentation/ui_components.dart';import '../domain/notification_entity.dart';import 'notification_providers.dart';class NotificationsScreen extends ConsumerWidget{const NotificationsScreen({super.key});Widget build(BuildContext c,WidgetRef r){final a=r.watch(notificationsProvider);return Scaffold(appBar:AppBar(title:const Text('Notifications')),body:a.when(data:(xs)=>xs.isEmpty?const EmptyStateWidget(message:'No notifications yet'):ListView.builder(padding:const EdgeInsets.all(12),itemCount:xs.length,itemBuilder:(_,i)=>_tile(c,r,xs[i])),loading:()=>const LoadingWidget(),error:(e,_)=>ErrorStateWidget(message:'Unable to load notifications: $e')));}Widget _tile(BuildContext c,WidgetRef r,NotificationEntity n)=>LuxuryCard(onTap:()async{if(!n.isRead)await r.read(notificationRepoProvider).markRead(n.id);if(c.mounted)c.push('/notifications/${n.id}',extra:n);},child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[if(!n.isRead)Container(width:8,height:8,margin:const EdgeInsets.only(top:6,right:10),decoration:const BoxDecoration(color:Color(0xffb9975b),shape:BoxShape.circle)),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(n.title,style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:5),Text(n.message,maxLines:2,overflow:TextOverflow.ellipsis),if(n.createdAt!=null)Text(n.createdAt!.toLocal().toString().split('.').first,style:Theme.of(c).textTheme.bodySmall)]))]));}
